-- Seed David Lloyd Clubs UK padel sites as members-only directory venues (24 Sep 2026)
--
-- Purpose: list all 71 David Lloyd UK clubs that have a padel page on davidlloyd.co.uk
-- (verified 24 Sep 2026) in the XPLAY club directory, so players can find them and
-- organise XPLAY matches there using the external-club "I've booked the court" flow.
--
-- Rule: external_provider = 'davidlloyd' means MEMBERS-ONLY, NEVER COLLECTED.
--   * No live availability grid, no collector, no member-account login (decision 24 Sep 2026).
--   * external_tenant_id is set to 'dl:<slug>' ON PURPOSE: the Playtomic/Padelmates collectors'
--     `map` modes only look at clubs with external_tenant_id IS NULL, and
--     dispatch_external_collect only picks provider in ('playtomic','padelmates'),
--     so these rows stay out of every collector without touching collector code.
--   * Six clubs were showing "Padel - Coming Soon" on 24 Sep 2026 (cheam, hamilton, kings-hill,
--     leicester-narborough, norwich, worcester): their description ends "Padel courts opening soon."
--
-- Data: name/address/postcode/phone/email from each club page's schema.org HealthClub JSON-LD;
-- coordinates from the club page's map pin (postcodes.io for the 7 pages without one).
--
-- Street excludes the town (city column holds it).
--
-- Rollback:
--   delete from public.clubs where external_provider = 'davidlloyd' and claimed = false;

on conflict (club_name) do update set
  source             = 'directory',
  external_provider  = 'davidlloyd',
  external_tenant_id = excluded.external_tenant_id,
  website            = excluded.website,
  latitude           = coalesce(clubs.latitude, excluded.latitude),
  longitude          = coalesce(clubs.longitude, excluded.longitude);
